// Simple Asteroid Dodger game
// Assumes a <canvas id="game"></canvas> exists in the page.

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas with id "game" not found');
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.clientWidth || 400;
  const height = canvas.height = canvas.clientHeight || 600;

  // Ship configuration
  const ship = {
    w: 40,
    h: 20,
    x: width / 2 - 20,
    y: height - 30,
    speed: 5,
  };

  // Game state
  const bullets = [];
  const asteroids = [];
  let score = 0;
  let lives = 3;
  let gameOver = false;

  // Input handling
  const keys = {};
  window.addEventListener('keydown', e => { keys[e.key] = true; });
  window.addEventListener('keyup', e => { keys[e.key] = false; });

  function spawnAsteroid() {
    const size = Math.random() * 30 + 20;
    asteroids.push({
      x: Math.random() * (width - size),
      y: -size,
      w: size,
      h: size,
      speed: Math.random() * 2 + 1,
    });
  }

  function update() {
    if (gameOver) return;
    // Move ship
    if (keys.ArrowLeft) ship.x = Math.max(0, ship.x - ship.speed);
    if (keys.ArrowRight) ship.x = Math.min(width - ship.w, ship.x + ship.speed);
    // Fire bullet
    if (keys[' '] && bullets.length < 5) {
      bullets.push({
        x: ship.x + ship.w / 2 - 2,
        y: ship.y,
        w: 4,
        h: 10,
        speed: 7,
      });
    }
    // Update bullets
    bullets.forEach(b => b.y -= b.speed);
    // Remove off‑screen bullets
    for (let i = bullets.length - 1; i >= 0; i--) {
      if (bullets[i].y + bullets[i].h < 0) bullets.splice(i, 1);
    }
    // Update asteroids
    asteroids.forEach(a => a.y += a.speed);
    // Collision detection
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      // Ship collision
      if (
        a.x < ship.x + ship.w && a.x + a.w > ship.x &&
        a.y < ship.y + ship.h && a.y + a.h > ship.y
      ) {
        lives--;
        asteroids.splice(i, 1);
        if (lives <= 0) {
          gameOver = true;
        }
        continue;
      }
      // Bullet collision
      for (let j = bullets.length - 1; j >= 0; j--) {
        const b = bullets[j];
        if (
          a.x < b.x + b.w && a.x + a.w > b.x &&
          a.y < b.y + b.h && a.y + a.h > b.y
        ) {
          score++;
          asteroids.splice(i, 1);
          bullets.splice(j, 1);
          break;
        }
      }
    }
    // Remove off‑screen asteroids
    for (let i = asteroids.length - 1; i >= 0; i--) {
      if (asteroids[i].y > height) asteroids.splice(i, 1);
    }
    // Randomly spawn new asteroids
    if (Math.random() < 0.02) spawnAsteroid();
  }

  function draw() {
    ctx.clearRect(0, 0, width, height);
    // Ship
    ctx.fillStyle = '#0f0';
    ctx.fillRect(ship.x, ship.y, ship.w, ship.h);
    // Bullets
    ctx.fillStyle = '#ff0';
    bullets.forEach(b => ctx.fillRect(b.x, b.y, b.w, b.h));
    // Asteroids
    ctx.fillStyle = '#a44';
    asteroids.forEach(a => ctx.fillRect(a.x, a.y, a.w, a.h));
    // HUD
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText(`Score: ${score}`, 10, 20);
    ctx.fillText(`Lives: ${lives}`, width - 80, 20);
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, width, height);
      ctx.fillStyle = '#fff';
      ctx.font = '30px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', width / 2, height / 2);
      ctx.font = '20px sans-serif';
      ctx.fillText(`Final Score: ${score}`, width / 2, height / 2 + 30);
    }
  }

  function loop() {
    update();
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }

  // Start game
  requestAnimationFrame(loop);
})();
